from lib import *
from t_realestate import re_state_var, STATE_HOOK, LEAD_LEASE

TEMPLATES = []
add = TEMPLATES.append

LEASE_WATCH = [
    "Security deposit limits, separate-account and interest rules, and return deadlines vary by state and sometimes by city. Check the state notes before setting the deposit.",
    "Many cities have rent control, just-cause eviction, registration or inspection rules that override lease terms. Verify locally.",
    "Notices of default, eviction or the right to cure for a primary residence are excluded from the federal E-SIGN Act. Serve those notices the way your state's law requires, usually on paper, even if the lease itself is signed electronically.",
    "Fair housing: do not screen, advertise or set terms based on race, color, religion, sex (including sexual orientation and gender identity), national origin, familial status or disability, or other classes protected by state and local law. Many places also prohibit discrimination based on source of income.",
    "Pre-1978 housing needs the federal lead-based paint disclosure and EPA pamphlet before the lease is signed. Many states also require disclosures about mold, flooding, bed bugs, radon or smoking policies.",
    "Landlords cannot lock out tenants, shut off utilities or remove belongings to force a move-out. Only a court can evict.",
]

# ------------------------------------------------------------------ Residential lease
add(T(
    id="residential-lease", title="Residential Lease Agreement", category="real-estate",
    tags=["lease", "rental", "landlord", "tenant", "apartment", "house", "state-aware", "most-signed"],
    summary="A plain-English lease for a house, apartment or unit: rent, deposit, maintenance, entry, pets and ending the lease.",
    useWhen="Renting an entire home or unit to a tenant for a fixed term or month to month. For renting a room in a shared home, use the room rental agreement.",
    watchOuts=LEASE_WATCH,
    stateAware=True, disclaimer=RE_DISCLAIMER,
    roles=[("landlord", "Landlord"), ("tenant", "Tenant")],
    variables=[
        re_state_var(),
        V("landlord_name", "Landlord name", "party", help="Owner or authorized manager."),
        V("landlord_address", "Landlord address for notices and rent", "address", help="Many states require the landlord to give an address for notices."),
        V("landlord_email", "Landlord email", "email", help="For routine communications."),
        V("tenant_name", "Tenant name(s)", "party", help="Every adult who will live there should sign."),
        V("tenant_email", "Tenant email", "email", help="For routine communications."),
        V("property_address", "Rental property address", "address", help="Including unit number."),
        V("furnished", "Furnished?", "bool", False, "false", help="If on, attach an inventory."),
        V("occupants", "Other occupants", "longtext", False, "None", help="Names of minors or other people who will live there."),
        V("term_type", "Lease type", "select", default="fixed term", options=["fixed term", "month to month"], help="Fixed term ends on a date. Month to month continues until notice."),
        V("start_date", "Start date", "date", help="Move-in date."),
        V("end_date", "End date", "date", False, help="For fixed-term leases."),
        V("after_term", "At the end of a fixed term", "select", False, "converts to month to month", ["converts to month to month", "ends unless renewed in writing"], help="What happens when the term ends."),
        V("rent", "Monthly rent", "money", help="Amount."),
        V("due_day", "Rent due day of month", "number", default="1", help="Day of the month."),
        V("payment_method", "How rent is paid", "text", default="by electronic transfer or check to the landlord", help="Methods accepted. Some states require a cash option or prohibit electronic-only payments."),
        V("grace_days", "Grace period (days)", "number", default="5", help="Days before a late fee applies. Some states set a minimum."),
        V("late_fee", "Late fee", "money", False, help="Must be reasonable. Several states cap late fees."),
        V("prorated_first", "Prorated first month rent", "money", False, help="If the lease starts mid-month."),
        V("deposit", "Security deposit", "money", help="Check the state's maximum."),
        V("deposit_held", "Where the deposit is held", "text", False, "", help="Some states require the bank name and address, a separate account or interest."),
        V("utilities_tenant", "Utilities paid by tenant", "longtext", default="Electricity, gas, internet", help="List."),
        V("utilities_landlord", "Utilities paid by landlord", "longtext", default="Water, sewer, trash", help="List."),
        V("pets", "Pets allowed?", "bool", False, "false", help="Assistance animals for people with disabilities are not pets and cannot be refused just because of a no-pets rule."),
        V("pet_terms", "Pet terms", "longtext", False, help="Type, number, pet deposit or rent (check state limits)."),
        V("smoking", "Smoking", "select", default="not allowed anywhere on the property", options=["not allowed anywhere on the property", "allowed only in designated outdoor areas"], help="Includes vaping and cannabis."),
        V("parking", "Parking", "text", False, "", help="Assigned spaces, garage, rules."),
        V("entry_notice_hours", "Notice before landlord entry (hours)", "number", default="24", help="Many states require 24 or 48 hours, except emergencies."),
        V("renters_insurance", "Require renters insurance?", "bool", False, "true", help="Protects the tenant's belongings and liability."),
        V("insurance_amount", "Minimum liability coverage", "money", False, "100000", help="Typical minimum."),
        V("notice_days", "Notice to end a month-to-month tenancy (days)", "number", default="30", help="Check the state's minimum. Some cities require more or require just cause."),
        V("built_before_1978", "Built before 1978?", "bool", False, "false", help="Adds the lead warning statement. Also sign the full federal disclosure form."),
        V("additional_terms", "Additional terms", "longtext", False, "None", help="Anything else."),
    ],
    sections=[
        S("Parties and property", "**Landlord:** {{landlord_name}}, {{landlord_address}} ({{landlord_email}})\n\n**Tenant:** {{tenant_name}} ({{tenant_email}})\n\nLandlord rents to Tenant the residence at {{property_address}} (the \"Premises\"), in {{state}}, for use only as a private residence by Tenant and these occupants: {{occupants}}."),
        opt("Furnishings", "The Premises are furnished. The furniture and appliances are listed in an attached inventory that both parties sign at move-in.", "furnished"),
        S("Term", "The lease starts on {{start_date}} and is a {{term_type}} tenancy."),
        when("Fixed term", "The lease ends on {{end_date}}. At the end of the term, the lease {{after_term}}.", "term_type == 'fixed term'"),
        when("Month to month", "Either party may end the tenancy by giving written notice at least {{notice_days}} days before the end of a rental period, or longer if the law requires.", "term_type == 'month to month'"),
        S("Rent", "Rent is {{rent}} per month, due on day {{due_day}} of each month, paid {{payment_method}}. First month's prorated rent, if any: {{prorated_first}}. If rent is not received within {{grace_days}} days after the due date, Tenant will pay a late fee of {{late_fee}}, to the extent allowed by law. A returned payment may result in a fee allowed by law. Landlord will give receipts on request."),
        S("Security deposit", "Tenant pays a security deposit of {{deposit}} before move-in. It is not a limit on Tenant's liability and may not be used by Tenant as the last month's rent unless Landlord agrees in writing. Deposit held at: {{deposit_held}}. After Tenant moves out and returns the keys, Landlord will return the deposit, with any interest the law requires, minus lawful deductions for unpaid rent and damage beyond normal wear and tear. Landlord will include an itemized statement of deductions within the deadline set by the law of {{state}}, sent to the forwarding address Tenant provides."),
        S("Move-in and move-out condition", "Before or at move-in, the parties will complete a written move-in checklist, with photos, signed by both. Tenant will leave the Premises clean and in the same condition at move-out, except for normal wear and tear."),
        S("Utilities", "Tenant pays: {{utilities_tenant}}. Landlord pays: {{utilities_landlord}}. Tenant will set up accounts in Tenant's name for utilities Tenant pays, starting on the start date."),
        S("Maintenance and repairs", "Landlord will keep the Premises in a safe and habitable condition, comply with building and health codes, and make necessary repairs within a reasonable time after notice, as the law requires. Tenant will keep the Premises clean and sanitary, use appliances and fixtures properly, replace smoke-alarm batteries if applicable, promptly report needed repairs, water leaks and mold in writing, and pay for damage caused by Tenant, occupants or guests beyond normal wear and tear. Tenant will not make alterations, paint or change locks without Landlord's written consent."),
        S("Landlord entry", "Landlord may enter at reasonable times to inspect, make repairs, or show the Premises, after giving at least {{entry_notice_hours}} hours' notice (or longer if the law requires), and at any time in an emergency."),
        S("Use and conduct", "Tenant will follow the law and any written community rules, not disturb neighbors, and not allow illegal activity on the Premises. Smoking (including vaping and cannabis) is {{smoking}}. Parking: {{parking}}. Guests staying more than 14 days in any six-month period need Landlord's written consent, to the extent the law allows."),
        opt("Pets", "Pets are allowed on these terms: {{pet_terms}}. Tenant is responsible for any damage or nuisance caused by pets. Assistance animals for people with disabilities are handled under fair housing law, not this section.", "pets"),
        S("No pets", "Unless the Pets section is included, no pets are allowed without Landlord's written consent. This does not apply to assistance animals for people with disabilities, which are handled under fair housing law."),
        opt("Renters insurance", "Tenant will keep renters insurance with at least {{insurance_amount}} of personal liability coverage and provide proof on request. Landlord's insurance does not cover Tenant's belongings.", "renters_insurance"),
        S("Assignment and subletting", "Tenant may not assign this lease or sublet any part of the Premises, including short-term rentals, without Landlord's written consent, which Landlord will not unreasonably withhold where the law requires."),
        S("Default and ending the lease", "If Tenant fails to pay rent or materially breaches this lease, Landlord may end the tenancy only by giving the notice and following the court process required by the law of {{state}}. Landlord will not lock out Tenant, shut off utilities or remove Tenant's belongings without a court order. If Tenant moves out early, Tenant remains responsible for rent until the earlier of the end of the term or the date a new tenant begins paying, and Landlord will make reasonable efforts to re-rent, as the law requires. Some states give tenants the right to end a lease early, for example for active military duty (federal Servicemembers Civil Relief Act) or for domestic violence."),
        when("Lead-based paint warning", "**Lead Warning Statement.** " + LEAD_LEASE + "\n\nLandlord and Tenant will also sign the full federal Lead-Based Paint Disclosure, and Tenant acknowledges receiving the EPA pamphlet \"Protect Your Family From Lead in Your Home.\" Tenant: [[initial:tenant]]", "built_before_1978 == true"),
        S("Required disclosures", "Landlord will provide all disclosures required by federal, state and local law (see the state notes for {{state}}), for example the identity of the owner or manager, mold, flood, radon or bed bug information, as applicable. Tenant acknowledges receiving any attached disclosures. Tenant: [[initial:tenant]]"),
        STATE_HOOK,
        S("Notices", "Routine communications may be sent by email. Legal notices, including notices to pay rent, cure a breach, terminate or vacate, will be delivered as required by the law of {{state}}, which may require paper delivery or posting, and also by email when allowed. Tenant's notice address is the Premises unless Tenant gives another in writing."),
        S("Additional terms", "{{additional_terms}}"),
        S("General", "This lease is governed by the law of {{state}}, and local ordinances where the Premises are located. Any term that conflicts with mandatory tenant protections is unenforceable to that extent, and the rest of the lease stays in effect. Each tenant who signs is jointly and severally responsible for all obligations. This is the entire agreement and can be changed only in writing signed by both parties. It may be signed electronically and in counterparts."),
        signatures([("landlord", "Landlord", "{{landlord_name}}", True), ("tenant", "Tenant", "{{tenant_name}}")]),
    ],
    sources=[SRC["turbotenant"], SRC["esign_exc"], SRC["lead_cfr"], SRC["lead_pamphlet"], SRC["hud_pm"], SRC["fha_3604"], src("Servicemembers Civil Relief Act, 50 U.S.C. §3955 (lease termination) (Cornell LII)", "https://www.law.cornell.edu/uscode/text/50/3955")],
))

# ------------------------------------------------------------------ Room rental / co-living
add(T(
    id="room-rental-agreement", title="Room Rental and Co-Living Agreement with House Rules", category="real-estate",
    tags=["room rental", "roommate", "co-living", "house rules", "lodger", "sublease", "state-aware"],
    summary="Rent a private room in a shared home, with shared-space rules, utilities, chores, guests and move-out terms.",
    useWhen="An owner or master tenant rents a bedroom in a home they share, or runs a co-living house where residents share common areas.",
    watchOuts=LEASE_WATCH[:4] + [
        "If you are a tenant renting out a room, your own lease probably requires the landlord's written consent to sublet. Subletting without it can get you evicted.",
        "Some states treat a single roomer in an owner-occupied home as a 'lodger' with faster removal procedures (for example California Civil Code §1946.5). Others give roommates full tenant rights. Verify locally.",
        "The federal Fair Housing Act exempts some owner-occupied buildings with four or fewer units from certain rules, but never from its advertising rules. Courts have held that choosing a roommate to share a living unit is outside the Act. State and local laws may still apply.",
        "Stays under 30 days may count as short-term rentals subject to city permits, taxes and bans.",
        "Co-living operators who rent many rooms may be running a rooming or boarding house that needs a license or inspection.",
    ],
    stateAware=True, disclaimer=RE_DISCLAIMER,
    roles=[("host", "Host (owner or master tenant)"), ("resident", "Resident")],
    variables=[
        re_state_var(),
        V("host_name", "Host name", "party", help="Owner or master tenant renting the room."),
        V("host_email", "Host email", "email", help="Email."),
        V("host_status", "Host is", "select", default="the owner of the home", options=["the owner of the home", "a tenant with written landlord consent to sublet"], help="A tenant needs the landlord's consent."),
        V("resident_name", "Resident name", "party", help="Person renting the room."),
        V("resident_email", "Resident email", "email", help="Email."),
        V("home_address", "Home address", "address", help="Address of the shared home."),
        V("room", "Room", "text", help="E.g. 'the northeast bedroom on the second floor, with the hall closet'."),
        V("private_bath", "Private bathroom?", "bool", False, "false", help="If off, bathrooms are shared."),
        V("shared_areas", "Shared areas", "longtext", default="Kitchen, living room, laundry room, back yard", help="Areas the resident may use."),
        V("off_limits", "Areas off-limits", "longtext", False, "Host's bedroom and bathroom, garage, storage closets", help="Areas the resident may not use."),
        V("start_date", "Move-in date", "date", help="Start."),
        V("term_type", "Term", "select", default="month to month", options=["month to month", "fixed term"], help="Length."),
        V("end_date", "End date", "date", False, help="For fixed terms."),
        V("rent", "Monthly rent", "money", help="Amount."),
        V("due_day", "Rent due day", "number", default="1", help="Day of month."),
        V("late_fee", "Late fee", "money", False, help="Reasonable amount. Check state caps."),
        V("deposit", "Security deposit", "money", help="Check state limits."),
        V("utilities", "Utilities", "select", default="included in rent", options=["included in rent", "split equally among residents", "split as stated in house rules"], help="How utilities are handled."),
        V("utility_cap", "Utility cap per month", "money", False, help="If included in rent, the host may charge for usage above this amount."),
        V("furnished", "Room furnished?", "bool", False, "false", help="List furniture in the inventory."),
        V("quiet_hours", "Quiet hours", "text", default="10:00 p.m. to 7:00 a.m. on weeknights, 11:00 p.m. to 8:00 a.m. on weekends", help="When noise must be kept low."),
        V("guest_policy", "Overnight guests", "text", default="no more than 3 nights in any 7-day period and 8 nights per month, with notice to housemates", help="Limits on overnight guests."),
        V("cleaning", "Cleaning and chores", "longtext", default="Clean up the kitchen right after use. Shared areas are cleaned on a rotating weekly schedule posted in the kitchen. Take out trash and recycling on your assigned weeks.", help="Chore expectations."),
        V("kitchen", "Kitchen and food", "longtext", default="Each resident has a labeled shelf in the refrigerator and pantry. Don't use others' food without asking. Shared staples may be split by agreement.", help="Food and kitchen rules."),
        V("smoking", "Smoking and vaping", "select", default="not allowed anywhere on the property", options=["not allowed anywhere on the property", "allowed only outside in designated areas"], help="Includes cannabis."),
        V("pets", "Resident may keep a pet?", "bool", False, "false", help="Assistance animals are handled under fair housing law."),
        V("pet_terms", "Pet terms", "longtext", False, help="Type and rules."),
        V("parking", "Parking", "text", False, "Street parking only", help="Parking rules."),
        V("entry_notice_hours", "Notice before host enters the room (hours)", "number", default="24", help="Except emergencies."),
        V("notice_days", "Notice to end (days)", "number", default="30", help="Check the state's minimum."),
        V("built_before_1978", "Home built before 1978?", "bool", False, "false", help="Adds the federal lead warning. Also sign the full federal disclosure."),
        V("other_rules", "Other house rules", "longtext", False, "Lock exterior doors when you leave. No parties without all housemates' agreement. Thermostat setting is decided together.", help="Anything else."),
    ],
    sections=[
        S("Parties and home", "**Host:** {{host_name}} ({{host_email}}), who is {{host_status}}.\n\n**Resident:** {{resident_name}} ({{resident_email}})\n\nHost rents to Resident {{room}} (the \"Room\") in the home at {{home_address}}, in {{state}} (the \"Home\"), for Resident's personal residence only."),
        when("Host is a tenant", "Host rents the Home from a landlord under a separate lease (the \"Master Lease\"). Host has the landlord's written consent to rent the Room. This agreement is subject to the Master Lease. Resident will follow the Master Lease's rules that Host provides in writing. If the Master Lease ends, this agreement ends too, and Host will give Resident as much notice as possible and refund prepaid rent and the deposit as required by law. Resident: [[initial:resident]]", "host_status == 'a tenant with written landlord consent to sublet'"),
        S("Shared and private space", "Resident has private use of the Room. Resident may use these shared areas in common with other residents: {{shared_areas}}. Off-limits: {{off_limits}}."),
        opt("Private bathroom", "Resident also has private use of the bathroom attached to the Room.", "private_bath"),
        opt("Furnishings", "The Room is furnished. Furniture is listed in a move-in inventory signed by both.", "furnished"),
        S("Term", "Starts {{start_date}}. Term: {{term_type}}."),
        when("Fixed term", "This agreement ends on {{end_date}} unless the parties agree in writing to extend it. After that, it continues month to month.", "term_type == 'fixed term'"),
        S("Rent and deposit", "Rent is {{rent}} per month, due on day {{due_day}}. Late fee after 5 days: {{late_fee}}, where allowed by law. Security deposit: {{deposit}}, returned after move-out minus lawful deductions, with an itemized statement, within the deadline set by the law of {{state}}."),
        S("Utilities", "Utilities (electricity, gas, water, trash and internet) are {{utilities}}."),
        when("Utility cap", "Rent includes utilities up to {{utility_cap}} per month for the Room's share. If a month's bills exceed the cap, Host may charge Resident its fair share of the excess with copies of the bills.", "utilities == 'included in rent'"),
        S("House rules", "Residents agree to follow these house rules, which are part of this agreement:\n\n- **Quiet hours:** {{quiet_hours}}.\n- **Overnight guests:** {{guest_policy}}. Residents are responsible for their guests.\n- **Cleaning and chores:** {{cleaning}}\n- **Kitchen and food:** {{kitchen}}\n- **Smoking and vaping:** {{smoking}}.\n- **Parking:** {{parking}}.\n- **Safety:** don't disable smoke or carbon monoxide alarms, block exits, or use space heaters or candles unattended.\n- **Other rules:** {{other_rules}}\n\nRules may be changed by the residents and Host together, in writing. Host will give at least 7 days' notice of any new rule, and new rules may not change rent, the deposit or the term. Resident: [[initial:resident]]"),
        opt("Pet", "Resident may keep: {{pet_terms}}. Resident is responsible for cleanup, noise and damage.", "pets"),
        S("Privacy and entry", "Host will not enter the Room without at least {{entry_notice_hours}} hours' notice and a reasonable purpose (repairs, inspection or showing), except in an emergency or with Resident's consent. Shared areas may be used by all residents at any time."),
        S("Repairs and damage", "Host keeps the Home safe and habitable and makes needed repairs after notice, as the law requires. Resident reports problems promptly and pays for damage Resident or Resident's guests cause beyond normal wear. Resident will not change locks, paint or make alterations without written consent."),
        S("Housemate disputes", "Residents will try to resolve disagreements directly and respectfully, then with Host's help. Repeated or serious violations of the house rules are a breach of this agreement after written notice and a chance to correct them."),
        S("Ending the agreement", "Either party may end a month-to-month arrangement with at least {{notice_days}} days' written notice, or longer if the law requires. Host may end the agreement for a serious breach only by following the notice and court procedures that apply under the law of {{state}} to the type of occupancy, such as tenant or lodger. Host will never use lockouts, utility shut-offs or removal of belongings to force a move. At move-out, Resident returns all keys and removes all belongings."),
        S("Required notices", "Legal notices, such as notices to pay rent or quit, will be delivered as required by the law of {{state}}, which may require paper delivery. Routine messages may be sent by email or text."),
        when("Lead warning (older homes)", "If the Home was built before 1978, Host will provide the federal lead-based paint disclosure and EPA pamphlet before Resident signs. " + LEAD_LEASE + " Resident: [[initial:resident]]", "built_before_1978 == true"),
        STATE_HOOK,
        S("General", "This agreement is governed by the law of {{state}} and applicable local law. Terms that conflict with mandatory protections are unenforceable to that extent. It is the entire agreement and may be changed only in writing. Electronic signatures are valid."),
        signatures([("host", "Host", "{{host_name}}"), ("resident", "Resident", "{{resident_name}}")]),
    ],
    sources=[SRC["fha_roommates"], SRC["fha_3604"], src("Fair Housing Council v. Roommate.com, 666 F.3d 1216 (9th Cir. 2012) (Justia)", "https://law.justia.com/cases/federal/appellate-courts/ca9/09-55272/09-55272-2012-02-02.html"), src("California Civil Code §1946.5 (lodgers)", "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1946.5"), SRC["turbotenant"], SRC["esign_exc"], SRC["lead_cfr"]],
))

# ------------------------------------------------------------------ Property management agreement
add(T(
    id="property-management-agreement", title="Property Management Agreement", category="real-estate",
    tags=["property management", "landlord", "rental", "manager", "fees"],
    summary="Hire a manager to lease, collect rent and maintain rental property, with fees, spending limits and trust-account rules.",
    useWhen="An owner hires a property manager or management company to run one or more rentals.",
    watchOuts=[
        "Most states require a real estate broker's license, or a property management license, to manage property for others for compensation. Check that the manager is licensed in the property's state. Unlicensed managers may not be able to collect fees.",
        "Tenant deposits and rents must usually be held in a trust account under state law. Ask how and where.",
        "Clarify who is the 'landlord' for legal notices, fair housing compliance and security deposit returns.",
        "Leasing fees, renewal fees, markups on maintenance and early termination fees are where costs hide. List them all.",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("owner", "Owner"), ("manager", "Manager")],
    variables=[V("effective_date", "Effective date", "date", help="Start date.")]
    + party_vars("owner", "Owner") + party_vars("manager", "Manager") + [
        V("manager_license", "Manager's license number and state", "text", help="Broker or property management license."),
        V("properties", "Properties managed", "longtext", help="Addresses and unit counts."),
        V("mgmt_fee", "Management fee (% of rent collected)", "percent", default="8", help="Percent of rents actually collected."),
        V("min_fee", "Minimum monthly fee per unit", "money", False, help="Optional minimum."),
        V("leasing_fee", "Leasing fee for a new tenant", "text", default="50% of one month's rent", help="Fee for finding and placing a tenant."),
        V("renewal_fee", "Lease renewal fee", "money", False, help="Fee for renewing a lease."),
        V("repair_limit", "Repair approval limit", "money", default="500", help="Manager may spend up to this per repair without the owner's approval, except in emergencies."),
        V("reserve", "Operating reserve", "money", default="500", help="Amount kept in the trust account for expenses."),
        V("statement_day", "Owner statements and distributions by day", "number", default="15", help="Day of the month."),
        V("markup", "Manager markup on maintenance", "select", default="no markup", options=["no markup", "up to 10% on third-party invoices"], help="Disclose any markup."),
        V("term_months", "Initial term (months)", "number", default="12", help="Initial term."),
        V("termination_days", "Notice to terminate (days)", "number", default="30", help="After the initial term."),
        V("insurance_amount", "Owner's minimum liability insurance", "money", default="1000000", help="Owner's landlord policy naming the manager as additional insured."),
        state_var(),
    ],
    sections=[
        S("Parties", party_line("owner", "Owner") + "\n\n" + party_line("manager", "Manager") + "\n\nManager holds license {{manager_license}}."),
        S("Appointment", "Owner appoints Manager as its exclusive agent to manage the following properties (the \"Properties\"), starting {{effective_date}}:\n\n{{properties}}"),
        S("Manager's duties", "Manager will, in Owner's name and for Owner's account:\n- advertise vacancies and screen applicants with written criteria applied consistently and in compliance with fair housing laws;\n- sign leases on Owner's approved terms, up to 12 months;\n- collect rents, deposits and other charges, and handle late notices and, with Owner's approval, evictions through an attorney;\n- arrange routine maintenance and repairs, and respond to emergencies 24 hours a day;\n- conduct move-in and move-out inspections with photos, and handle deposit accounting within legal deadlines;\n- keep complete records and comply with laws that apply to the Properties."),
        S("Money and trust account", "Manager will hold all rents, deposits and Owner funds in a trust account as required by the law of {{governing_state}}, separate from Manager's own funds. Manager may keep an operating reserve of {{reserve}}. By day {{statement_day}} of each month, Manager will send Owner a statement of income and expenses and distribute the balance, minus the reserve and Manager's fees."),
        S("Spending authority", "Manager may approve repairs up to {{repair_limit}} per item without Owner's prior approval. Larger repairs need Owner's approval, except in an emergency threatening life, health or serious property damage, when Manager may act and tell Owner promptly. Manager's markup on maintenance: {{markup}}. Manager will disclose any ownership interest or affiliation with vendors it hires."),
        S("Fees", "Owner will pay Manager:\n- a management fee of {{mgmt_fee}}% of rents actually collected, with a minimum of {{min_fee}} per unit per month if stated;\n- a leasing fee of {{leasing_fee}} for each new tenant;\n- a renewal fee of {{renewal_fee}} for each renewal, if stated.\n\nNo other fees are charged unless Owner agrees in writing."),
        S("Owner's responsibilities", "Owner will keep the Properties in a condition that complies with habitability laws, fund repairs and reserves, carry property and liability insurance of at least {{insurance_amount}} naming Manager as an additional insured, provide all required disclosures and documents, and not interfere with Manager's lawful performance. Owner remains responsible for mortgage payments and property taxes, unless Manager agrees in writing to pay them from funds held."),
        S("Fair housing", "Owner and Manager will comply with federal, state and local fair housing laws. Manager will not follow any instruction that would violate them."),
        S("Liability", "Manager will indemnify Owner for losses caused by Manager's negligence, willful misconduct or breach. Owner will indemnify Manager for claims arising from the condition of the Properties or Owner's acts, except those caused by Manager's negligence or misconduct."),
        S("Term and termination", "The initial term is {{term_months}} months, renewing month to month after that. After the initial term, either party may terminate with {{termination_days}} days' written notice. Either party may terminate on 10 days' notice for an uncured material breach. On termination, Manager will within 30 days deliver all funds, deposits (with an accounting), leases, keys and records to Owner, and notify tenants where to pay rent."),
        general_terms(),
        signatures([("owner", "Owner", "{{owner_name}}", True), ("manager", "Manager", "{{manager_name}}", True)]),
    ],
    sources=[SRC["hud_pm"], SRC["fha_3604"], SRC["trec"], SRC["esign"]],
))

# ------------------------------------------------------------------ Bird dog
add(T(
    id="bird-dog-agreement", title="Bird Dog (Lead Referral) Agreement", category="real-estate",
    tags=["bird dog", "lead", "referral", "investor", "wholesale", "finder"],
    summary="Pay a 'bird dog' a fee for finding off-market property leads, while limiting their role to providing information.",
    useWhen="A real estate investor pays someone to find potential properties and owner contact information, but the investor does all negotiation.",
    watchOuts=[
        "Licensing is the main risk. In most states, receiving compensation for procuring, negotiating or helping with a sale on someone else's behalf is brokerage activity that requires a license. A fee that depends on a deal closing looks more like a commission. Licensees are generally prohibited from paying unlicensed people for referrals. Verify locally before paying any fee.",
        "Some states' wholesaling laws also cover people who market or solicit for wholesalers. Check the state notes.",
        "Bird dogs must not represent themselves as agents or investors' representatives, negotiate price, or pressure owners. Telemarketing and texting rules (TCPA, Do Not Call) apply to cold outreach.",
        "Respect privacy: skip-traced data and owner contact information may be subject to state privacy laws and the source's terms of use.",
        "Collect a Form W-9 and issue Form 1099 as required.",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("investor", "Investor"), ("birddog", "Bird dog")],
    variables=[V("effective_date", "Effective date", "date", help="Start date.")]
    + party_vars("investor", "Investor") + party_vars("birddog", "Bird dog") + [
        V("criteria", "Property criteria", "longtext", help="Areas, property types, condition, price range."),
        V("lead_info", "What a lead must include", "longtext", default="Property address, owner name if known, how the bird dog learned of it, property condition notes and photos taken from public places.", help="Minimum information for a lead."),
        V("fee_model", "Fee model", "select", default="flat fee per accepted lead", options=["flat fee per accepted lead", "flat fee paid only if investor buys the property"], help="A fee paid only if a deal closes increases licensing risk. Verify locally."),
        V("lead_fee", "Fee per accepted lead", "money", False, help="Paid for each lead the investor accepts as new and qualifying."),
        V("closing_fee", "Fee if investor buys", "money", False, help="Flat amount, not a percentage of price."),
        V("protection_months", "Lead credit period (months)", "number", default="6", help="How long a submitted lead stays credited to the bird dog."),
        V("bird_dog_licensed", "Is the bird dog a licensed real estate professional?", "bool", False, "false", help="Licensees must follow their brokerage and license-law rules, and fees may need to go through their broker."),
        state_var(),
    ],
    sections=[
        S("Parties", party_line("investor", "Investor") + "\n\n" + party_line("birddog", "Bird dog") + "\n\nEffective {{effective_date}}."),
        S("What the bird dog does", "Bird dog will look for properties that match the Investor's criteria:\n\n{{criteria}}\n\nand submit leads in writing that include: {{lead_info}}\n\nBird dog's role is limited to finding and passing along information."),
        S("What the bird dog will not do", "Bird dog will not:\n- negotiate price or terms, make offers, or sign anything for Investor;\n- claim to be a real estate agent, broker or Investor's representative, or say they will be paid if a sale happens;\n- enter property without permission, harass owners, or use deceptive tactics; or\n- contact people in violation of telemarketing, texting, do-not-call or privacy laws.\n\nBird dog: [[initial:birddog]]"),
        S("Accepting leads", "Investor will tell Bird dog within 5 business days whether a lead is accepted. A lead is accepted only if Investor did not already know about the property and it meets the criteria. Investor's records decide which leads were already known. An accepted lead stays credited to Bird dog for {{protection_months}} months."),
        when("Fee: per accepted lead", "Investor will pay Bird dog {{lead_fee}} for each accepted lead, within 15 days after acceptance, whether or not Investor ever buys the property.", "fee_model == 'flat fee per accepted lead'"),
        when("Fee: if investor buys", "If Investor or its affiliate buys an accepted lead property within the credit period, Investor will pay Bird dog a flat fee of {{closing_fee}} within 10 days after closing. **The parties understand this fee structure may require a real estate license in some states, and each party has checked the law of {{governing_state}}.** Investor: [[initial:investor]] Bird dog: [[initial:birddog]]", "fee_model == 'flat fee paid only if investor buys the property'"),
        opt("Licensed bird dog", "Bird dog holds a real estate license. Bird dog will comply with license-law and brokerage rules, disclose their license status to owners as required, and any fee will be paid through Bird dog's broker if required.", "bird_dog_licensed"),
        S("Independent contractor", "Bird dog is an independent contractor, uses their own methods, pays their own expenses and taxes, and will provide a Form W-9. This agreement is not exclusive."),
        S("Confidentiality", "Each party will keep leads, Investor's criteria and deal terms confidential. Bird dog will not share submitted leads with others during the credit period."),
        S("Term", "Either party may end this agreement at any time by written notice. Fees for leads accepted before the end are still payable on the terms above."),
        general_terms(),
        signatures([("investor", "Investor", "{{investor_name}}", True), ("birddog", "Bird dog", "{{birddog_name}}")]),
    ],
    sources=[SRC["wholesale_tracker"], SRC["il_454"], SRC["tx_oc1101"], src("FCC: Telephone Consumer Protection Act and robocall/robotext rules", "https://www.fcc.gov/general/telemarketing-and-robocalls"), SRC["irs_ic"]],
))
